                        q.append((ny,nx))
            comps.append((min(y for y, x in cells), min(x for y, x in cells), cells))
    if comps:
        top = min(item[0] for item in comps)
        obj = min((item for item in comps if item[0] == top), key=lambda item: item[1])
        for y, x in obj[2]:
            out[y][x] = 0
