 "content": "from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen, comps = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            y0, x0 = min(y for y,x in cells), min(x for y,x in cells)
            mask = frozenset((y-y0, x-x0) for y,x in cells)
            comps.append((color, cells, mask))
    # Two matching, separately placed objects have different colors in these tasks;
    # recolor the upper copy with the lower copy's color.
    for i, a in enumerate(comps):
        for b in comps[i+1:]:
            if a[2] == b[2] and a[0] != b[0]:
                upper, lower = (a,b) if min(y for y,x in a[1]) < min(y for y,x in b[1]) else (b,a)
                for y,x in upper[1]:
                    out[y][x] = lower[0]
                return out
    return out

